package com.growworld.service;
import com.growworld.domain.User; import com.growworld.dto.AuthDtos.*; import com.growworld.repository.UserRepository; import com.growworld.security.JwtService; import jakarta.servlet.http.HttpServletResponse; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseCookie; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import static org.springframework.http.HttpStatus.*;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt;private final boolean secureCookie;public AuthService(UserRepository u,PasswordEncoder p,JwtService j,@Value("${app.cookie-secure}") boolean s){users=u;passwords=p;jwt=j;secureCookie=s;} @Transactional public UserResponse register(RegisterRequest r,HttpServletResponse res){var email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmail(email))throw new ResponseStatusException(CONFLICT,"このメールアドレスは登録済みです");var u=users.save(new User(email,passwords.encode(r.password()),r.displayName().trim()));setCookie(res,jwt.create(u.getId()));return view(u);} public UserResponse login(LoginRequest r,HttpServletResponse res){var u=users.findByEmail(r.email().trim().toLowerCase(Locale.ROOT)).filter(x->passwords.matches(r.password(),x.getPasswordHash())).orElseThrow(()->new ResponseStatusException(UNAUTHORIZED,"メールアドレスまたはパスワードが正しくありません"));setCookie(res,jwt.create(u.getId()));return view(u);} public void logout(HttpServletResponse res){res.addHeader("Set-Cookie",ResponseCookie.from("GW_AUTH","").path("/").httpOnly(true).secure(secureCookie).sameSite("Lax").maxAge(0).build().toString());} public UserResponse me(UUID id){return view(users.findById(id).orElseThrow(()->new ResponseStatusException(UNAUTHORIZED)));} private void setCookie(HttpServletResponse res,String token){res.addHeader("Set-Cookie",ResponseCookie.from("GW_AUTH",token).path("/").httpOnly(true).secure(secureCookie).sameSite("Lax").maxAge(604800).build().toString());} private UserResponse view(User u){return new UserResponse(u.getId(),u.getDisplayName(),u.getEmail());}}
